using namespace std;

struct Point { int x; int y; };

Point makePoint(int x, int y) {     // 一次返回两个值
    return Point{x, y};
}

void print(Point p) {               // 只传一个参数
    cout << "(" << p.x << ", " << p.y << ")" << endl;
}

int main() {
    // 对比:两个独立变量
    int x = 3, y = 4;
    cout << "两个 int: " << x << ", " << y << endl;

    // 结构体:一个整体
    Point p{3, 4};
    print(p);                       // 传一个就行

    // 数组:100 个点
    Point pts[3] = {{1,1}, {2,2}, {3,3}};
    for (auto& q : pts) print(q);

    // 函数返回:一次给两个值
    Point m = makePoint(5, 6);
    print(m);
}
```

