using namespace std;

struct Point { int x, y; };

struct Vec3 {
    double v[3];           // 结构体里装数组
    double& operator[](int i) { return v[i]; }
};

int main() {
    // 数组
    int p[2] = {3, 4};
    cout << "数组 p[0]=" << p[0] << " p[1]=" << p[1] << "  <- 0 是 x 还是 y?\n";

    // 结构体
    Point q{3, 4};
    cout << "结构体 q.x=" << q.x << " q.y=" << q.y << "  <- 名字自解释\n";

    // 结构体里装数组:两全
    Vec3 a{{1,2,3}};
    for (int i = 0; i < 3; i++) a[i] *= 2;
    for (int i = 0; i < 3; i++) cout << a[i] << " ";
    cout << endl;
}
```

